with filtered as (select id, device_code, reading_ts, humidity, firmware, round(temp_c, 0) temp_c_rounded from device_readings where reading_ts > to_date('2025-09-01') and status_bits between 4 and 11), enriched as (select *, first_value(humidity, true) over (partition by device_code order by temp_c_rounded, id rows between unbounded preceding and current row) first_known_humidity, lead(humidity, 2) over (partition by device_code order by humidity, id) next_humidity, round(humidity / sum(humidity) over (partition by device_code), 4) humidity_share from filtered), filtered_device_readings as (select id, reading_ts, humidity, firmware, temp_c_rounded, first_known_humidity, next_humidity, humidity_share, concat_ws('-', device_code, firmware) device_code_firmware_key from enriched where first_known_humidity is not null), valid as (select id, reading_ts, humidity, firmware, temp_c_rounded, first_known_humidity, next_humidity, humidity_share, device_code_firmware_key, humidity - first_known_humidity humidity_minus_first_known_humidity from filtered_device_readings where reading_ts > to_timestamp('2025-09-01 02:00:00') and firmware not in ('2.0.1', '1.1.0')), scored as (select *, row_number() over (order by humidity_minus_first_known_humidity desc, id) seq_no, avg(first_known_humidity) over (order by humidity, id rows between 2 preceding and 1 preceding) first_known_humidity_avg_2_prior, sum(humidity_minus_first_known_humidity) over w_running running_humidity_minus_first_known_humidity, sum(humidity_share) over (order by cast(reading_ts as bigint) range between 1800 preceding and current row) humidity_share_sum_30m from valid where humidity <= 55 window w_running as (order by humidity, id rows between unbounded preceding and current row)), with_windows as (select id, reading_ts, humidity, firmware, temp_c_rounded, next_humidity, humidity_share, device_code_firmware_key, first_known_humidity_avg_2_prior, running_humidity_minus_first_known_humidity, lead(running_humidity_minus_first_known_humidity) over (order by first_known_humidity, id) next_running_humidity_minus_first_known_humidity, lead(first_known_humidity_avg_2_prior) over (order by first_known_humidity, id) next_first_known_humidity_avg_2_prior, lag(first_known_humidity_avg_2_prior) over (order by first_known_humidity, id) prev_first_known_humidity_avg_2_prior, row_number() over (order by first_known_humidity, id) seq_no_2 from scored) select id, reading_ts, humidity, firmware, temp_c_rounded, first_known_humidity_avg_2_prior, next_first_known_humidity_avg_2_prior, prev_first_known_humidity_avg_2_prior from with_windows order by temp_c_rounded nulls first, next_first_known_humidity_avg_2_prior;
